"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/conversion-funnel/variants/01-overview";
export interface ArtemisConversionFunnelProps { className?: string;  }
export function ArtemisConversionFunnel({ className }: ArtemisConversionFunnelProps) { return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><Variant0/></ArtemisScope>; }

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { useId, useRef, useState, type KeyboardEvent } from "react";
import { Bar, BarChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { ArtemisButton } from "../../../foundations/button";
import { ArtemisDigitSwap } from "../../../foundations/digit-swap";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
type Stage = {
    id: string;
    label: string;
    value: number;
    detail: string;
};
type Period = {
    id: string;
    label: string;
    stages: readonly Stage[];
};
const DETAILS = {
    visits: "Unique people who visited your website.",
    signup: "Visitors who created a workspace.",
    active: "Workspaces that completed their first project.",
    paid: "Activated workspaces that chose a paid plan.",
} as const;
function stages(values: readonly [
    number,
    number,
    number,
    number
]): Stage[] {
    return [
        { id: "visits", label: "Visitors", value: values[0], detail: DETAILS.visits },
        { id: "signup", label: "Sign-ups", value: values[1], detail: DETAILS.signup },
        { id: "active", label: "Activated", value: values[2], detail: DETAILS.active },
        { id: "paid", label: "Customers", value: values[3], detail: DETAILS.paid },
    ];
}
const PERIODS: readonly Period[] = [
    { id: "week", label: "7 days", stages: stages([12840, 6420, 3852, 1541]) },
    { id: "month", label: "30 days", stages: stages([52680, 23706, 14224, 5932]) },
];
const COLORS = ["#dbeafe", "#bfdbfe", "#93c5fd", "#60a5fa"] as const;
const LAYER_OPACITY = [0.14, 0.24] as const;
const INDICATOR_TRANSITION = { type: "spring", stiffness: 170, damping: 24, mass: 1.2 } as const;
const PANEL_TRANSITION = { duration: 0.2, ease: ARTEMIS_EASE_OUT };
const TAB_BASE = "art:relative art:z-10 art:inline-flex art:items-center art:justify-center art:whitespace-nowrap art:bg-transparent art:font-medium art:outline-none art:transition-colors art:duration-150 art:motion-reduce:delay-0 art:motion-reduce:transition-none";
const TAB_ACTIVE = `${TAB_BASE} art:delay-100 art:rounded-full art:h-7 art:px-3 art:py-0 art:text-xs art:focus-visible:ring-2 art:focus-visible:ring-ring art:text-foreground`;
const TAB_IDLE = `${TAB_BASE} art:text-muted-foreground art:delay-0 art:hover:text-foreground art:rounded-full art:h-7 art:px-3 art:py-0 art:text-xs art:focus-visible:ring-2 art:focus-visible:ring-ring`;
const fmt = (n: number) => n.toLocaleString("en-US");
type Row = {
    name: string;
    value: number;
    full: number;
    index: number;
};
type ShapeProps = {
    x?: number;
    y?: number;
    width?: number;
    height?: number;
    index?: number;
};
function FunnelSegment({ props, rows, selected, }: {
    props: ShapeProps;
    rows: readonly Row[];
    selected: number;
}) {
    const { x = 0, y = 0, width = 0, height = 0, index = 0 } = props;
    const first = rows[0]?.value ?? 1;
    const row = rows[index];
    if (!row)
        return null;
    const next = rows[index + 1] ?? row;
    const scale = 0.38 * (height + 2 * y);
    const cy = y + height / 2;
    const halfL = (scale * row.value) / first;
    const halfR = (scale * next.value) / first;
    const right = x + width;
    const h = x + width * 0.42;
    const c = x + width * 0.74;
    const color = COLORS[index] ?? COLORS[0];
    const layers = [12, 6, 0].map((pad, layer) => {
        const tl = cy - (halfL + pad);
        const tr = cy - (halfR + pad);
        const br = cy + (halfR + pad);
        const bl = cy + (halfL + pad);
        const d = `M ${x},${tl} H ${h} C ${c},${tl} ${c},${tr} ${right},${tr} V ${br} C ${c},${br} ${c},${bl} ${h},${bl} H ${x} Z`;
        const opacity = layer < 2 ? LAYER_OPACITY[layer] : selected === index ? 1 : 0.85;
        return <path key={pad} fill={color} d={d} opacity={opacity}/>;
    });
    const mid = x + width / 2;
    return (<g>
      {layers}
      <rect x={mid - 24} y={cy - 13} width="48" height="26" rx="13" fill="var(--artemis-background)"/>
      <text x={mid} y={cy} textAnchor="middle" dominantBaseline="central" fill="var(--artemis-foreground)" className="art:text-xs art:font-medium" pointerEvents="none">
        {Math.round((row.value / first) * 100)}
        {"%"}
      </text>
    </g>);
}
type TooltipPayload = ReadonlyArray<{
    payload?: unknown;
}>;
function TooltipCard({ active, payload }: {
    active?: boolean;
    payload?: TooltipPayload;
}) {
    const row = payload?.[0]?.payload as Row | undefined;
    if (!active || !row)
        return null;
    return (<div className="art:rounded-xl art:border art:border-border art:bg-background art:px-3 art:py-2 art:text-xs">
      <p className="art:font-medium">{row.name}</p>
      <p className="art:mt-1 art:text-muted-foreground">
        {fmt(row.value)}
        {" people"}
      </p>
    </div>);
}
export default function ConversionFunnelOverview() {
    const id = useId();
    const [periodIndex, setPeriodIndex] = useState(0);
    const [stageIndex, setStageIndex] = useState(3);
    const tabRefs = useRef<Array<HTMLButtonElement | null>>([]);
    const reduce = useReducedMotion() ?? false;
    const period = PERIODS[periodIndex] ?? PERIODS[0];
    const list = period.stages;
    const first = list[0];
    const last = list[list.length - 1];
    const stage = list[stageIndex] ?? last;
    const prev = stageIndex > 0 ? list[stageIndex - 1] : undefined;
    const rate = ((last.value / first.value) * 100).toFixed(1);
    const rows: Row[] = list.map((s, index) => ({ name: s.label, value: s.value, full: 1, index }));
    const selectPeriod = (next: number, focus: boolean) => {
        setPeriodIndex(next);
        setStageIndex((PERIODS[next] ?? PERIODS[0]).stages.length - 1);
        if (focus)
            tabRefs.current[next]?.focus();
    };
    const onTabKey = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
        const count = PERIODS.length;
        let next: number | null = null;
        if (event.key === "ArrowRight")
            next = (index + 1) % count;
        else if (event.key === "ArrowLeft")
            next = (index - 1 + count) % count;
        else if (event.key === "Home")
            next = 0;
        else if (event.key === "End")
            next = count - 1;
        if (next === null)
            return;
        event.preventDefault();
        selectPeriod(next, true);
    };
    return (<>
      <section aria-label="Conversion funnel" className="art:w-full art:max-w-2xl art:rounded-3xl art:border art:border-border art:bg-background art:p-5 art:@min-[640px]/artemis:p-6">
        <header className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-3">
          <h2 className="art:text-4xl art:font-medium">
            {"Conversion funnel"}
          </h2>
          <div>
            <div role="tablist" className="art:inline-flex art:items-center art:rounded-full art:gap-0 art:bg-muted art:p-1" aria-label="Funnel period">
              {PERIODS.map((p, index) => {
            const active = index === periodIndex;
            return (<div key={p.id} className="art:relative">
                    {active ? (<motion.span layout="position" layoutId={`${id}-period-indicator`} className="art:absolute art:inset-0 art:rounded-full art:bg-background" style={{ borderRadius: 9999 }} transition={reduce ? { duration: 0 } : INDICATOR_TRANSITION}/>) : null}
                    <button ref={(node) => {
                    tabRefs.current[index] = node;
                }} type="button" role="tab" aria-selected={active} className={active ? TAB_ACTIVE : TAB_IDLE} id={`${id}-${index}`} aria-controls={`${id}-chart`} tabIndex={active ? 0 : -1} onClick={() => selectPeriod(index, false)} onKeyDown={(event) => onTabKey(event, index)}>
                      {p.label}
                    </button>
                  </div>);
        })}
            </div>
          </div>
        </header>
        <div className="art:my-6">
          <p className="art:mb-1 art:text-sm art:text-muted-foreground">
            {"Visitor to customer"}
          </p>
          <div className="art:flex art:items-center art:justify-between art:gap-4">
            <span className="art:inline-flex art:items-center art:text-4xl art:font-medium art:leading-none art:tracking-tight">
              <ArtemisDigitSwap value={rate} className="art:[&_[data-slot=digit-swap-glyph]:nth-last-child(2)]:w-[0.4ch]"/>
              <span>
                {"%"}
              </span>
            </span>
            <p className="art:flex art:items-center art:gap-1 art:text-xs art:text-muted-foreground">
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-3.5" aria-hidden="true">
                <path d="M7 7h10v10"/>
                <path d="M7 17 17 7"/>
              </svg>
              {fmt(last.value)}
              {" conversions"}
            </p>
          </div>
        </div>
        <div role="tabpanel" id={`${id}-chart`} aria-labelledby={`${id}-${periodIndex}`} className="art:h-56 art:w-full art:@min-[640px]/artemis:h-64">
          <ResponsiveContainer width="100%" height="100%" minWidth={0}>
            <BarChart data={rows} margin={{ top: 8, right: 8, bottom: 8, left: 8 }} barCategoryGap={2}>
              <XAxis dataKey="name" hide/>
              <YAxis hide domain={[0, 1]}/>
              <Tooltip cursor={false} content={(props) => <TooltipCard active={props.active} payload={props.payload}/>}/>
              <Bar dataKey="full" className="art:cursor-pointer" isAnimationActive={false} shape={(props: ShapeProps) => <FunnelSegment props={props} rows={rows} selected={stageIndex}/>} onClick={(_data: unknown, index: number) => setStageIndex(index)}/>
            </BarChart>
          </ResponsiveContainer>
        </div>
        <div className="art:mt-3 art:flex art:flex-wrap art:gap-1.5">
          {list.map((s, index) => {
            const pressed = index === stageIndex;
            return (<ArtemisButton key={s.id} variant="ghost" size="sm" className={pressed ? "art:bg-muted art:text-foreground art:h-9" : "art:h-9"} aria-pressed={pressed} onClick={() => setStageIndex(index)}>
                <span aria-hidden="true" className="art:size-2.5 art:rounded-full" style={{ backgroundColor: COLORS[index] }}/>
                {s.label}
              </ArtemisButton>);
        })}
        </div>
        <motion.div key={`${period.id}-${stage.id}`} className="art:mt-5 art:border-t art:border-border art:pt-5" initial={reduce ? false : { opacity: 0, y: 4 }} animate={{ opacity: 1, y: 0 }} transition={PANEL_TRANSITION}>
          <div className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-x-4 art:gap-y-2">
            <p className="art:flex art:items-center art:gap-2 art:text-sm art:font-medium">
              {stage.label}
              <span className="art:text-muted-foreground">
                {fmt(stage.value)}
              </span>
            </p>
            {prev ? (<p className="art:flex art:items-center art:gap-1 art:text-xs art:text-muted-foreground">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-down art:size-3.5" aria-hidden="true">
                  <path d="M12 5v14"/>
                  <path d="m19 12-7 7-7-7"/>
                </svg>
                {((1 - stage.value / prev.value) * 100).toFixed(1)}
                {"% drop-off"}
              </p>) : null}
          </div>
          <p className="art:mt-1 art:text-xs art:leading-relaxed art:text-muted-foreground">
            {stage.detail}
          </p>
        </motion.div>
      </section>
    </>);
}
